-- Fixture-only source value history. No product, provider, signer, or authority table is referenced.
CREATE OR REPLACE FUNCTION source_value_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'source value history is immutable'; END $$;
CREATE TABLE IF NOT EXISTS source_value_runs(operator_test_id text NOT NULL,run_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(operator_test_id,run_hash));
CREATE TABLE IF NOT EXISTS source_value_citations(operator_test_id text NOT NULL,run_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,run_hash,artifact_hash),FOREIGN KEY(operator_test_id,run_hash) REFERENCES source_value_runs(operator_test_id,run_hash));
CREATE TABLE IF NOT EXISTS source_value_role_statuses(operator_test_id text NOT NULL,run_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,run_hash,artifact_hash),FOREIGN KEY(operator_test_id,run_hash) REFERENCES source_value_runs(operator_test_id,run_hash));
CREATE TABLE IF NOT EXISTS source_value_estimates(operator_test_id text NOT NULL,run_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,run_hash,artifact_hash),FOREIGN KEY(operator_test_id,run_hash) REFERENCES source_value_runs(operator_test_id,run_hash));
CREATE TABLE IF NOT EXISTS source_value_request_claims(operator_test_id text NOT NULL,idempotency_key text NOT NULL,request_hash char(64) NOT NULL,run_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,idempotency_key),FOREIGN KEY(operator_test_id,run_hash) REFERENCES source_value_runs(operator_test_id,run_hash));
DO $$ DECLARE tab text; BEGIN FOREACH tab IN ARRAY ARRAY['source_value_runs','source_value_citations','source_value_role_statuses','source_value_estimates','source_value_request_claims'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS source_value_immutable ON %I',tab); EXECUTE format('CREATE TRIGGER source_value_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION source_value_append_only()',tab); END LOOP; END $$;
CREATE INDEX IF NOT EXISTS source_value_run_scope_idx ON source_value_runs(operator_test_id,created_at);
